import fetchMock from 'jest-fetch-mock';
import { ApiClient } from './apiClient';

beforeEach(() => {
  fetchMock.resetMocks();
});

interface Item { id: number; name: string; }

test('GET returns typed data', async () => {
  fetchMock.mockResponseOnce(JSON.stringify({ id: 1, name: 'test' }));
  const client = new ApiClient('http://api.example.com');
  const item = await client.get<Item>('/items/1');
  expect(item.id).toBe(1);
  expect(item.name).toBe('test');
  expect(fetchMock).toHaveBeenCalledWith('http://api.example.com/items/1', expect.any(Object));
});

test('GET throws ApiError on non-2xx', async () => {
  fetchMock.mockResponseOnce('Not Found', { status: 404 });
  const client = new ApiClient('http://api.example.com');
  await expect(client.get('/missing')).rejects.toMatchObject({ status: 404 });
});

test('POST sends JSON body', async () => {
  fetchMock.mockResponseOnce(JSON.stringify({ id: 2, name: 'created' }));
  const client = new ApiClient('http://api.example.com');
  const result = await client.post<Item, { name: string }>('/items', { name: 'created' });
  expect(result.id).toBe(2);
  const call = fetchMock.mock.calls[0];
  expect(call[1]?.method).toBe('POST');
  expect(call[1]?.headers).toMatchObject({ 'Content-Type': 'application/json' });
});

test('POST throws ApiError on 500', async () => {
  fetchMock.mockResponseOnce('Server Error', { status: 500 });
  const client = new ApiClient('http://api.example.com');
  await expect(client.post('/items', {})).rejects.toMatchObject({ status: 500 });
});
